@BeforeModelTrigger('$last-action.name = "EN_Bell_vr_cfl_faq" OR $last-action.name = "FR_Bell_vr_cfl_faq" OR $last-action.name = "EN_Bell_vr_cda_faq" OR $last-action.name = "FR_Bell_vr_cda_faq"')
def _check_faq():
  # Added the CDA tools to the valid data source list
  valid_ds = ["EN_Bell_vr_cfl_faq", "FR_Bell_vr_cfl_faq", "EN_Bell_vr_cda_faq", "FR_Bell_vr_cda_faq"]

  last_action = [action for action in history.actions if hasattr(action, 'action') and action.action in valid_ds][-1]
  input_params = history.playbook_input.action_parameters
  dcx_action_code = input_params['dcx_action_code']
  language = input_params['language'] 

  snippets = last_action.output.get('200', {}).get('snippets', [])
  if (len(snippets) > 0):
    faq_title = snippets[0].get('title', None)
    # Note: Ensure that CDA tool also returns dcx_action_code as the title 
    # to pass this validation.
    if (faq_title == dcx_action_code):
      answer = last_action.output.get('200', {}).get('answer', '')
      return answer

  return "answer not found"
  # respond("Je suis désolé, je n'ai pas de réponse à cette question. Vérifions si le processus en arrière-plan est terminé." if language == "fr-ca" else "I am sorry, I dont have answer to that question. Meanwhile let's check if the background process has completed.")

